  .hud{position:fixed;top:12px;right:14px;z-index:10;font-size:12px;line-height:1.5;text-align:right;background:rgba(10,14,20,.7);
    border:1px solid rgba(255,255,255,.14);border-radius:10px;padding:7px 11px;min-width:150px}
  .group{display:flex;gap:5px;align-items:center}
  .glabel{font-size:10px;text-transform:uppercase;letter-spacing:.08em;opacity:.65;margin-right:2px}
  button{background:#1c2635;color:#e8edf4;border:1px solid rgba(255,255,255,.18);border-radius:8px;padding:6px 11px;font-size:13px;cursor:pointer}
  button:hover{background:#27344a}
  button.on{background:#b3372e;border-color:#e06a60;color:#fff}
  button.primary{background:#b3372e;border-color:#e06a60;color:#fff}
  #settings{position:fixed;top:56px;left:14px;z-index:11;width:252px;max-height:calc(100vh - 150px);overflow:auto;background:rgba(10,14,20,.88);
    backdrop-filter:blur(10px);border:1px solid rgba(255,255,255,.14);border-radius:14px;padding:12px 14px;display:none}
  #settings.open{display:block}
  #settings h3{margin:2px 0 8px;font-size:12px;text-transform:uppercase;letter-spacing:.09em;opacity:.8}
  #settings h3:not(:first-child){margin-top:14px}
  .row{display:flex;justify-content:space-between;align-items:center;gap:8px;margin:4px 0;font-size:12px}
  .row label{opacity:.9}
  .row input{width:78px;background:#131c29;color:#e8edf4;border:1px solid rgba(255,255,255,.2);border-radius:6px;padding:4px 6px;font-size:12px}
  .sbtns{display:flex;gap:6px;margin-top:12px}
  .sbtns button{flex:1}
</style>
<script type="importmap">
