</html>","replace":"addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);});

/* ---------- procedural textures ---------- */
function canvasTex(w,h,fn,rx=1,ry=1){
  const c=document.createElement('canvas');c.width=w;c.height=h;fn(c.getContext('2d'),w,h);
  const t=new THREE.CanvasTexture(c);t.wrapS=t.wrapT=THREE.RepeatWrapping;t.repeat.set(rx,ry);
  t.colorSpace=THREE.SRGBColorSpace;t.anisotropy=4;return t;
}
const asphaltTex=canvasTex(512,512,(g,w,h)=>{const r=mulberry32(7);g.fillStyle='#33373c';g.fillRect(0,0,w,h);
  for(let i=0;i<9000;i++){const v=40+r()*50;g.fillStyle=`rgb(${v},${v+3},${v+7})`;g.fillRect(r()*w,r()*h,2,2);}
  for(let i=0;i<40;i++){g.fillStyle='rgba(0,0,0,.12)';g.beginPath();g.ellipse(r()*w,r()*h,10+r()*40,5+r()*14,r()*3,0,7);g.fill();}},10,2);
const grassTex=canvasTex(256,256,(g,w,h)=>{const r=mulberry32(11);g.fillStyle='#4d7a3d';g.fillRect(0,0,w,h);
  for(let i=0;i<5000;i++){g.fillStyle=`rgb(${55+r()*40},${105+r()*55},${40+r()*30})`;g.fillRect(r()*w,r()*h,2,3);}},24,24);
function brickTex(seed,base){return canvasTex(128,64,(g,w,h)=>{const r=mulberry32(seed);g.fillStyle=base;g.fillRect(0,0,w,h);
  for(let i=0;i<700;i++){g.fillStyle=r()>.5?'rgba(0,0,0,.13)':'rgba(255,220,190,.10)';g.fillRect(r()*w,r()*h,2,2);}
  g.strokeStyle='rgba(0,0,0,.25)';g.strokeRect(1,1,w-2,h-2);});}

/* ---------- shared materials ---------- */
const MAT={
  paint:new THREE.MeshPhysicalMaterial({color:0xb3202a,metalness:0.65,roughness:0.32,clearcoat:1,clearcoatRoughness:0.12,envMapIntensity:1.2}),
  paintDark:new THREE.MeshPhysicalMaterial({color:0x2a2e35,metalness:0.6,roughness:0.45,clearcoat:0.6,envMapIntensity:0.8}),
  glass:new THREE.MeshPhysicalMaterial({color:0x9fd4e8,metalness:0,roughness:0.06,transmission:0.75,transparent:true,opacity:0.55,envMapIntensity:1.6,side:THREE.DoubleSide}),
  shard:new THREE.MeshPhysicalMaterial({color:0xbfe8f5,metalness:0,roughness:0.05,transparent:true,opacity:0.65,envMapIntensity:1.8,side:THREE.DoubleSide}),
  tire:new THREE.MeshStandardMaterial({color:0x14161a,roughness:0.95,metalness:0.05}),
  rim:new THREE.MeshStandardMaterial({color:0xc9ced6,roughness:0.25,metalness:0.95,envMapIntensity:1.2}),
  light:new THREE.MeshStandardMaterial({color:0xfff6cf,emissive:0xffedb5,emissiveIntensity:2.2,roughness:0.3}),
  tail:new THREE.MeshStandardMaterial({color:0x7a0d12,emissive:0xb01018,emissiveIntensity:1.4,roughness:0.3}),
  chrome:new THREE.MeshStandardMaterial({color:0xd7dbe0,roughness:0.18,metalness:1,envMapIntensity:1.3}),
  interior:new THREE.MeshStandardMaterial({color:0x22242a,roughness:0.9}),
};
const brickMats=['#9c4a38','#a8553f','#8f4232','#b05a40'].map((c,i)=>new THREE.MeshStandardMaterial({map:brickTex(100+i*17,c),roughness:0.94,metalness:0.02}));

/* ---------- simulation state ---------- */
let world=null, dynGroup=null, pairs=[], joints=[], carParts=[], bricks=[];
let chassisBody=null, noseBody=null, wallX=12, carStartX=-15, impacted=false, brokenCount=0, totalJoints=0;
let dust=null, dustVel=null, dustLife=0, shake=0, skidL=null, skidR=null, blob=null;
let physMats=null;
const FIXED=1/120;
let accumulator=0;

function boxMesh(sx,sy,sz,mat){
  const m=new THREE.Mesh(new THREE.BoxGeometry(sx,sy,sz),mat);
  m.castShadow=true;m.receiveShadow=true;return m;
}
function makeBody(mass,sx,sy,sz,x,y,z,matBody,opts={}){
  const body=new CANNON.Body({mass,shape:new CANNON.Box(new CANNON.Vec3(sx/2,sy/2,sz/2)),
    position:new CANNON.Vec3(x,y,z),material:matBody,linearDamping:opts.ld??0.01,angularDamping:opts.ad??0.05,
    allowSleep:opts.sleep??false,sleepSpeedLimit:0.35,sleepTimeLimit:0.6});
  if(opts.quat)body.quaternion.copy(opts.quat);
  world.addBody(body);return body;
}
function pair(body,object3d){dynGroup.add(object3d);pairs.push({body,obj:object3d});return object3d;}
function lockJoint(a,b,threshold,kind){
  const c=new CANNON.LockConstraint(a,b,{maxForce:1e7});
  world.addConstraint(c);
  const j={c,a,b,threshold,kind,broken:false,d0:a.position.distanceTo(b.position)};
  joints.push(j);totalJoints++;return j;
}
function breakJoint(j){
  if(j.broken)return;j.broken=true;brokenCount++;
  world.removeConstraint(j.c);
  j.a.wakeUp();j.b.wakeUp();
}
</script>
</body>
</html>"}

