  for(let x=-half;x<=half;x+=10){
    for(const zz of [-TW/2-3.2,TW/2+3.2]){
      const p=new THREE.Mesh(new THREE.CylinderGeometry(0.07,0.09,5.5,8),poleMat);p.position.set(x,2.75,zz);g.add(p);
      const head=new THREE.Mesh(new THREE.BoxGeometry(0.7,0.14,0.3),MAT.light);head.position.set(x,5.5,zz);g.add(head);}}
