/* ---------- wall ---------- */
function buildWall(){
  const {cols,rows,depth,bw,bh,bd,brickMass}=S;
  const gap=0.012, geo=new THREE.BoxGeometry(bd,bh,bw); // x=depth, y=height, z=width (across track)
