    const z=(c-(cols-1)/2)*(bw+gap)+stagger-(r%2?bw*0.0:0);
    const x=wallX+(d-(depth-1)/2)*(bd+gap);
    const y=bh/2+0.03+r*(bh+gap);
    const body=makeBody(brickMass,bd,bh,bw,x,y,z,physMats.brick,{sleep:true,ld:0.02,ad:0.08});
    body.wakeUpAfterNarrowphase=true;
    const mesh=new THREE.Mesh(geo,brickMats[(idx*7+r*3+c)%brickMats.length]);
    mesh.castShadow=true;mesh.receiveShadow=true;
    pair(body,mesh);bricks.push(body);
    body.sleepState=0; // awake but settled by tiny y offset; solver settles it
    idx++;
  }
}
