/* ---------- impact FX (visual only, seeded) ---------- */
function buildDust(){
  const N=260, pos=new Float32Array(N*3); dustVel=new Float32Array(N*3);
  const geo=new THREE.BufferGeometry(); geo.setAttribute('position',new THREE.BufferAttribute(pos,3));
  dust=new THREE.Points(geo,new THREE.PointsMaterial({color:0xcbb59a,size:0.16,transparent:true,opacity:0,depthWrite:false}));
  dust.frustumCulled=false; dynGroup.add(dust);
}
function registerImpact(iv,pos){
  if(impacted&&iv<6)return;
  if(!impacted){impacted=true;shake=Math.min(0.5,iv*0.02);
    const r=mulberry32(42); const p=dust.geometry.attributes.position.array;
    for(let i=0;i<p.length;i+=3){
      p[i]=pos.x+(r()-0.5)*1.2; p[i+1]=Math.max(0.1,pos.y+(r()-0.5)*1.4); p[i+2]=pos.z+(r()-0.5)*2.4;
      dustVel[i]=2+r()*7; dustVel[i+1]=r()*4.5; dustVel[i+2]=(r()-0.5)*7;}
    dust.geometry.attributes.position.needsUpdate=true; dustLife=1.6; dust.material.opacity=0.75;
  } else shake=Math.max(shake,Math.min(0.3,iv*0.012));
}
function updateDust(dt){
  if(!dust||dustLife<=0)return; dustLife-=dt;
  const p=dust.geometry.attributes.position.array;
  for(let i=0;i<p.length;i+=3){p[i]+=dustVel[i]*dt;p[i+1]+=dustVel[i+1]*dt;p[i+2]+=dustVel[i+2]*dt;dustVel[i+1]-=2.2*dt;if(p[i+1]<0.05)p[i+1]=0.05;}
  dust.geometry.attributes.position.needsUpdate=true;
  dust.material.opacity=Math.max(0,Math.min(0.75,dustLife*0.5));
}

/* ---------- rebuild the whole run from S ---------- */
const GRP={ground:1,brick:2,car:4,debris:8};
function rebuild(){
  if(dynGroup){scene.remove(dynGroup);dynGroup.traverse(o=>{if(o.geometry)o.geometry.dispose();});}
  dynGroup=new THREE.Group(); scene.add(dynGroup);
  pairs=[];joints=[];carParts=[];bricks=[];impacted=false;brokenCount=0;totalJoints=0;accumulator=0;dustLife=0;shake=0;
  wallX=S.track/2-8; carStartX=-S.track/2+5;

  world=new CANNON.World({gravity:new CANNON.Vec3(0,-S.gravity,0)});
  world.broadphase=new CANNON.SAPBroadphase(world);
  world.allowSleep=true;
  world.solver.iterations=12;
  world.defaultContactMaterial.friction=0.5;

  physMats={ground:new CANNON.Material('ground'),brick:new CANNON.Material('brick'),
    car:new CANNON.Material('car'),glass:new CANNON.Material('glass'),wheel:new CANNON.Material('wheel')};
  const cm=(a,b,f,r)=>world.addContactMaterial(new CANNON.ContactMaterial(a,b,{friction:f,restitution:r,contactEquationStiffness:1e7,contactEquationRelaxation:3}));
  cm(physMats.brick,physMats.brick,S.bFric,S.bRest);
  cm(physMats.brick,physMats.ground,S.gFric,S.bRest);
  cm(physMats.brick,physMats.car,Math.min(1,(S.bFric+S.gFric)/2),S.bRest);
  cm(physMats.brick,physMats.glass,S.bFric*0.6,0.25);
  cm(physMats.brick,physMats.wheel,S.bFric,0.2);
  cm(physMats.car,physMats.ground,S.gFric,0.08);
  cm(physMats.glass,physMats.ground,S.gFric*0.6,0.3);
  cm(physMats.wheel,physMats.ground,S.gFric,0.25);
  cm(physMats.car,physMats.car,0.4,0.1);
  cm(physMats.car,physMats.glass,0.3,0.2);
  cm(physMats.car,physMats.wheel,0.4,0.15);
  cm(physMats.glass,physMats.glass,0.2,0.3);
  cm(physMats.wheel,physMats.wheel,0.5,0.3);
  cm(physMats.glass,physMats.wheel,0.3,0.25);

  const groundBody=new CANNON.Body({mass:0,material:physMats.ground,shape:new CANNON.Plane(),
    collisionFilterGroup:GRP.ground,collisionFilterMask:-1});
  groundBody.quaternion.setFromAxisAngle(new CANNON.Vec3(1,0,0),-Math.PI/2);
  groundBody.position.y=0.03; // top of the asphalt slab
  world.addBody(groundBody);

  buildEnvironment(); buildWall(); buildCar(); buildDust();

  for(const b of bricks){b.collisionFilterGroup=GRP.brick;b.collisionFilterMask=-1;}
  for(const b of carParts){b.collisionFilterGroup=GRP.car;b.collisionFilterMask=GRP.ground|GRP.brick|GRP.debris;b._debris=false;}

  // tight shadow frustum on track / car / wall
  const c=sun.shadow.camera; c.left=-30;c.right=30;c.top=22;c.bottom=-22;c.near=2;c.far=90;c.updateProjectionMatrix();
  sun.position.set(wallX-14,30,16); sun.target.position.set(wallX-10,0,0);
  if(camMode==='orbit'){controls.target.set(wallX-4,1,0);}
  $('hudState').textContent='driving';
}

/* ---------- per-step physics housekeeping ---------- */
function physicsStep(){
  // drive: hold target speed until the nose reaches the wall (engine, not a script)
  if(!impacted&&chassisBody){
    const noseX=noseBody?niseX(noseBody):chassisBody.position.x;
    if(noseX<wallX-1.2){
      for(const b of carParts){
        if(b._debris)continue;
        b.velocity.x=S.speed;
        if(b.velocity.y<-0.5)b.velocity.y=-0.5;
        b.angularVelocity.scale(0.6,b.angularVelocity);
      }
    }
  }
  world.step(FIXED);
  // joints also fail when stretched apart, or when the chassis sheds speed in the hit
  if(chassisBody){
    const drop=S.speed-chassisBody.velocity.x;
    for(const j of joints){
      if(j.broken)continue;
      const d=j.a.position.distanceTo(j.b.position);
      if(d>j.d0+0.38)breakJoint(j);
      else if(impacted&&drop>j.threshold*1.45)breakJoint(j);
    }
    // fully detached parts become debris and start colliding with the car/each other
    for(const b of carParts){
      if(b._debris||b===chassisBody)continue;
      const mine=joints.filter(j=>j.a===b||j.b===b);
      if(mine.length&&mine.every(j=>j.broken)){
        b._debris=true;b.collisionFilterGroup=GRP.debris;b.collisionFilterMask=-1;b.wakeUp();
      }
    }
  }
}
function niseX(b){return b.position.x;}
